VERSION = '0.18.1'
RUNTIME = Path('/home/alihu/ki-video/studio')
PAYLOAD_SHA256 = 'fe732750d2e274799a3862c600d3f4650552437d8e4f93d6173f8ff37db2d5f6'
PAYLOAD = ''


def atomic(path, data):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + '.' + uuid.uuid4().hex + '.partial')
    try:
        with temp.open('xb') as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temp, path)
    finally:
        temp.unlink(missing_ok=True)


def install_release(runtime):
    raw = base64.b64decode(PAYLOAD)
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise RuntimeError('Die heruntergeladene Installationsdatei ist beschädigt.')
    target = runtime / 'releases' / (VERSION + '_' + PAYLOAD_SHA256[:12])
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        if sum(x.file_size for x in archive.infolist()) > 5_000_000:
            raise RuntimeError('Unerwartete Paketgröße.')
        for item in archive.infolist():
            path = Path(item.filename)
            if path.is_absolute() or '..' in path.parts or item.is_dir():
                raise RuntimeError('Ungültiger Paketpfad.')
            data = archive.read(item.filename)
            dest = target / path
            if path.suffix == '.py': ast.parse(data.decode('utf-8'), filename=str(path))
            if dest.exists() and dest.read_bytes() != data:
                raise RuntimeError('Eine installierte Programmdatei wurde verändert. Sie bleibt erhalten: ' + str(dest))
            if not dest.exists(): atomic(dest, data)
    return target


def http_json(url, method='GET', body=None, token=None):
    headers = {'Content-Type': 'application/json'}
    if token: headers['X-Cay-Token'] = token
    request = urllib.request.Request(url, data=json.dumps(body).encode() if body is not None else None, headers=headers, method=method)
    with urllib.request.urlopen(request, timeout=5) as response:
        return json.load(response)


def health(url):
    try: return http_json(url + '/api/health')
    except (OSError, ValueError): return None


def jobs_exist(runtime):
    path = runtime / 'data/cay_studio.sqlite3'
    if not path.is_file(): raise RuntimeError('Die vorhandene Studio-Datenbank wurde nicht gefunden.')
    with sqlite3.connect(str(path)) as db:
        chat = db.execute("SELECT COUNT(*) FROM chat_jobs WHERE status IN ('queued','running')").fetchone()[0]
        exists = db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='image_jobs'").fetchone()
        pictures = db.execute("SELECT COUNT(*) FROM image_jobs WHERE status IN ('queued','submitting','submitted','uncertain')").fetchone()[0] if exists else 0
        has_factory = db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='factory_runs'").fetchone()
        has_control=db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='factory_control'").fetchone()
        def pending(table,states):
            join=' LEFT JOIN factory_control c ON c.id=r.id' if has_control else ''
            guard=' AND COALESCE(c.paused,0)=0' if has_control else ''
            return db.execute(f'SELECT COUNT(*) FROM {table} r'+join+' WHERE r.state IN ('+states+')'+guard).fetchone()[0]
        factory = pending('factory_runs',"'planning','pictures','voicing','rendering','correcting','audio_mixing','finishing'") if has_factory else 0
        if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='remix_runs'").fetchone():factory+=pending('remix_runs',"'tracking','rendering','finishing'")
        return chat + pictures + factory > 0


def verify_process(pid, runtime, release):
    if not isinstance(pid, int) or pid <= 1: raise RuntimeError('Ungültige Dashboard-Prozesskennung.')
    proc = Path('/proc') / str(pid)
    if proc.stat().st_uid != os.getuid(): raise RuntimeError('Der Dashboard-Prozess gehört einem anderen Nutzer.')
    args = proc.joinpath('cmdline').read_bytes().split(b'\0')
    expected_python = str(runtime / 'venv/bin/python').encode()
    expected_server = str(release / 'server.py').encode()
    if expected_python not in args or expected_server not in args:
        raise RuntimeError('Der laufende Prozess gehört nicht eindeutig zu dieser Studio-Installation. Er wurde nicht beendet.')


def stop_dashboard(info, runtime, release):
    pid = info['pid']
    verify_process(pid, runtime, release)
    # pidfd binds the signal to this process even if the PID is recycled later.
    if hasattr(os, 'pidfd_open') and hasattr(signal, 'pidfd_send_signal'):
        fd = os.pidfd_open(pid)
        try:
            verify_process(pid, runtime, release)
            signal.pidfd_send_signal(fd, signal.SIGTERM)
        finally: os.close(fd)
    else:
        verify_process(pid, runtime, release)
        os.kill(pid, signal.SIGTERM)
    deadline = time.monotonic() + 25
    while time.monotonic() < deadline:
        proc = Path(f'/proc/{pid}/stat')
        try:
            # A reaped process or a zombie no longer has an active server.
            if proc.read_text().rsplit(')', 1)[1].split()[0] == 'Z': return
        except FileNotFoundError: return
        time.sleep(.2)
    raise RuntimeError('Dashboard beendet sich noch nicht. Kein erzwungenes Beenden ausgeführt. Bitte später erneut starten.')


def switch_release(runtime, release):
    current = runtime / 'current'
    if current.exists() and not current.is_symlink(): raise RuntimeError('current ist kein Studio-Verweis; nichts überschrieben.')
    temp = runtime / ('current_' + uuid.uuid4().hex)
    temp.symlink_to(release, target_is_directory=True)
    os.replace(temp, current)


def start_dashboard(runtime, release, url, maintenance=False):
    logs = runtime / 'logs'; logs.mkdir(exist_ok=True)
    env = os.environ.copy()
    env['CAY_STUDIO_RUNTIME'] = str(runtime)
    env['CAY_STUDIO_START_MAINTENANCE'] = '1' if maintenance else '0'
    args = [str(runtime / 'venv/bin/python'), str(release / 'server.py')]
    with (logs / 'dashboard.log').open('ab') as log:
        process = subprocess.Popen(args, cwd=release, env=env, stdin=subprocess.DEVNULL, stdout=log, stderr=log, start_new_session=True)
    atomic(logs / 'dashboard_prozess.json', json.dumps({'pid': process.pid, 'args': args}).encode())
    deadline = time.monotonic() + 25
    while time.monotonic() < deadline:
        if process.poll() is not None: raise RuntimeError('Neue Dashboard-Version startet nicht. Siehe logs/dashboard.log.')
        info = health(url)
        if info and info.get('pid') == process.pid: return info
        time.sleep(.2)
    # Clean up only the process we just started, using graceful termination.
    stop_dashboard({'pid': process.pid}, runtime, release)
    raise RuntimeError('Dashboard meldet sich nicht rechtzeitig. Siehe logs/dashboard.log.')


def backup_database(runtime, root):
    folder = root / '06_Sicherungen/Dashboard' / ('Vor_Update_' + time.strftime('%Y%m%d_%H%M%S') + '_' + uuid.uuid4().hex[:6])
    folder.mkdir(parents=True, exist_ok=False)
    target = folder / 'cay_studio.sqlite3'
    with sqlite3.connect(str(runtime / 'data/cay_studio.sqlite3')) as source:
        with sqlite3.connect(str(target)) as destination:
            source.backup(destination)
            if destination.execute('PRAGMA integrity_check').fetchone()[0] != 'ok':
                raise RuntimeError('Datenbanksicherung konnte nicht bestätigt werden. Update angehalten.')
    shutil.copy2(runtime / 'config/ablage.json', folder / 'ablage.json')
    return folder


def install_sampler_adapter(runtime, release):
    source = release / 'comfy_sampler_compat.py'
    target = runtime.parent / 'apps/ComfyUI/custom_nodes/cay_studio_sampler/__init__.py'
    data = source.read_bytes()
    if target.exists():
        previous = target.read_bytes()
        if previous == data: return
        if b'CAY_STUDIO_COMPAT' not in previous[:250]:
            raise RuntimeError('Der Zielordner cay_studio_sampler enthält eine fremde Erweiterung. Nichts überschrieben.')
        backup = runtime / 'backups' / ('sampler_' + hashlib.sha256(previous).hexdigest()[:16] + '.py')
        backup.parent.mkdir(parents=True, exist_ok=True)
        if not backup.exists(): atomic(backup, previous)
    target.parent.mkdir(parents=True, exist_ok=True)
    atomic(target, data)


def version_key(text):
    try: return tuple(int(x) for x in str(text).split('.'))
    except ValueError: return None


def activate(runtime, root, release, url):
    current = runtime / 'current'
    if not current.is_symlink(): raise RuntimeError('Eine vorhandene Studio-Installation mit current-Verweis wird benötigt.')
    old = current.resolve(strict=True)
    previous = health(url)
    if previous and (previous.get('app') != 'CayStudio' or previous.get('root') != str(root.resolve())):
        raise RuntimeError('Auf diesem Port läuft eine andere Anwendung. Es wurde nichts beendet.')
    # Never an older version over a newer one: its projects would fail in the old code. Without a running
    # dashboard the installed version comes from the release folder name (releases/<VERSION>_<sha12>).
    installed = previous.get('version') if previous else old.name.split('_', 1)[0]
    if version_key(installed) and version_key(installed) > version_key(VERSION):
        raise RuntimeError('Auf diesem PC ist schon die neuere Version ' + str(installed) + ' installiert. Dieses ältere Update wurde nicht ausgeführt, dein Studio bleibt, wie es ist. Nimm bitte das neueste Update.')
    if previous and previous.get('version') == VERSION and old == release:
        install_sampler_adapter(runtime, release)
        if previous.get('maintenance'):
            token = http_json(url + '/api/bootstrap')['csrf']
            http_json(url + '/api/system/maintenance', 'POST', {'enabled': False}, token)
        return None
    if previous is None:
        address = urllib.parse.urlsplit(url)
        with socket.socket() as sock:
            sock.settimeout(.5)
            if sock.connect_ex((address.hostname, address.port)) == 0:
                raise RuntimeError('Dashboard-Port ist belegt, aber die Anwendung meldet keinen gültigen Status. Nichts beendet.')
    if jobs_exist(runtime):
        raise RuntimeError('Ein KI-Auftrag läuft oder wartet. Nach seinem Abschluss denselben Updatebefehl erneut starten.'+' Hängt ein Abschnitt: PC neu starten, Cay_Studio_Starten.cmd öffnen, dann dieses Update erneut starten.')
    stopped, new_info = False, None
    try:
        if previous:
            verify_process(previous['pid'], runtime, old)
            token = http_json(url + '/api/bootstrap')['csrf']
            try:
                http_json(url + '/api/system/maintenance', 'POST', {'enabled': True}, token)
            except urllib.error.HTTPError as error:
                if error.code != 404: raise RuntimeError('Dashboard ist noch beschäftigt: ein Abschnitt läuft oder hängt.'+' Hängt ein Abschnitt: PC neu starten, Cay_Studio_Starten.cmd öffnen, dann dieses Update erneut starten.')
                # Version 0.1 has no maintenance endpoint; inspect its queue again.
                if jobs_exist(runtime): raise RuntimeError('Ein KI-Auftrag wurde gestartet. Update später erneut starten.')
            print('Aktualisiere nur das Dashboard. ComfyUI und Ollama laufen weiter.', flush=True)
            stop_dashboard(previous, runtime, old); stopped = True
        # A request already accepted by 0.1 may have queued while it was shutting down.
        if jobs_exist(runtime): raise RuntimeError('Während des Updates wurde ein KI-Auftrag angelegt. Vorherige Version wird wieder gestartet.')
        backup = backup_database(runtime, root)
        install_sampler_adapter(runtime, release)
        switch_release(runtime, release)
        new_info = start_dashboard(runtime, release, url, maintenance=True)
        if new_info.get('version') != VERSION or new_info.get('root') != str(root.resolve()):
            raise RuntimeError('Die neue Version meldet einen unerwarteten Stand.')
        token = http_json(url + '/api/bootstrap')['csrf']
        http_json(url + '/api/system/maintenance', 'POST', {'enabled': False}, token)
        return backup
    except Exception:
        if new_info:
            stop_dashboard(new_info, runtime, release)
        switch_release(runtime, old)
        if stopped or previous is None:
            start_dashboard(runtime, old, url)
            print('Vorherige Dashboard-Version wieder gestartet. Projekte und Chat bleiben erhalten.', flush=True)
        elif previous and previous.get('version') != '0.1.0':
            try: http_json(url + '/api/system/maintenance', 'POST', {'enabled': False}, token)
            except Exception: pass
        raise


def main():
    print('CAY STUDIO 0.18.1 — FIGUREN-BIBLIOTHEK, TITELBILD, SCHNITT, BENACHRICHTIGUNGEN', flush=True)
    if sys.platform != 'linux' or not os.path.ismount('/mnt/d'):
        raise RuntimeError('Im Ubuntu-/WSL-Terminal starten. D: muss unter /mnt/d erreichbar sein.')
    config = json.loads((RUNTIME / 'config/ablage.json').read_text(encoding='utf-8'))
    root = Path(config['wsl_root']).resolve()
    if root != Path('/mnt/d/Cay_Studio').resolve() or not root.is_dir(): raise RuntimeError('Studio-Ablage auf D: nicht erreichbar.')
    python = RUNTIME / 'venv/bin/python'
    if not python.is_file(): raise RuntimeError('Vorhandene Dashboard-Umgebung nicht gefunden.')
    with (RUNTIME / 'dashboard_install.lock').open('a') as install_lock, (RUNTIME / 'start.lock').open('a') as start_lock:
        try:
            fcntl.flock(install_lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            fcntl.flock(start_lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError: raise RuntimeError('Studio startet oder aktualisiert bereits. Bitte kurz warten.')
        release = install_release(RUNTIME)
        check = "from importlib.metadata import version; import json,sys; req=json.loads(sys.argv[1]); assert all(version(n)==v for n,v in req.items()),'Dashboard-Pakete stimmen nicht mit der vorhandenen Version überein'"
        requirements = dict(line.split('==') for line in (release / 'requirements.lock').read_text().splitlines() if line.strip())
        subprocess.run([str(python), '-I', '-c', check, json.dumps(requirements)], check=True)
        print('Vorhandene Dashboard-Pakete geprüft. Keine Installation oder Modelldownloads.', flush=True)
        backup = activate(RUNTIME, root, release, 'http://127.0.0.1:8787')
        docs = root / '90_System/Dashboard' / VERSION; docs.mkdir(parents=True, exist_ok=True)
        shutil.copy2(release / 'README_DE.md', docs / 'README_DE.md')
        atomic(docs / 'Installationsstand.json', json.dumps({'version': VERSION, 'release': str(release), 'payload_sha256': PAYLOAD_SHA256, 'backup': str(backup) if backup else None}, indent=2).encode())
        tool = root / '90_System/Werkzeuge' / ('Cay_Studio_Update_Produktion_' + VERSION + '_' + PAYLOAD_SHA256[:8] + '.py')
        if not tool.exists(): shutil.copy2(Path(__file__).resolve(), tool)
    subprocess.run([str(python), str(release / 'launcher.py'), '--open-browser'], check=True)
    print('\n=== CAY STUDIO 0.18.1 INSTALLIERT ===', flush=True)
    print('Kein PC-Neustart nötig. ComfyUI und Ollama laufen weiter.', flush=True)
    print('Keine neuen Modelle nötig. Das neue Studio öffnet sich unter http://127.0.0.1:8787, das bisherige unter /classic.', flush=True)
    print('Danach im Browser Strg+F5 drücken: unten muss 0.18.1 stehen.', flush=True)
    print('Neue Filme starten mit Qualität Standard und Autopilot. Laufende Projekte laufen weiter und behalten ihren Schnitt.', flush=True)
    print('Benachrichtigungen aufs Handy: Zahnrad oben rechts, Benachrichtigungen (freiwillig, kostenlos).', flush=True)
    print('Für mehr Tempo: Zahnrad oben rechts, Turbo einrichten, danach PC einmal neu starten.', flush=True)
    print('Projekte, Bilder, Stimmen und fertige Abschnitte bleiben erhalten.', flush=True)
    print('Dashboard: http://localhost:8787', flush=True)
    if backup: print('Sicherung: ' + str(backup), flush=True)


if __name__ == '__main__':
    try: main()
    except Exception as error:
        print('\nUPDATE ANGEHALTEN: ' + str(error), file=sys.stderr)
        print('Bitte diese Meldung zurückschicken. Keine Grundinstallation ausführen.', file=sys.stderr)
        sys.exit(1)
